var n=[{title:`Ce qui change la charge sur vos genoux`,text:`La profondeur du squat, la hauteur de la marche, l’équilibre, la vitesse, la résistance et l’impact des sauts modifient tous le travail de vos genoux. Il n’existe pas de règle universelle selon laquelle le genou ne doit jamais dépasser les orteils. La distance que votre genou peut parcourir confortablement diffère d’une personne à l’autre et d’une tâche à l’autre.`},{title:`Alternatives pratiques`,text:`Un passage contrôlé de assis à debout, un squat bulgare avec appui ou une montée sur petite marche peuvent être plus faciles à apprendre qu’un squat sauté rapide. Une version moins profonde ou plus lente peut être plus confortable dans certains cas. Quand l’impact pose problème, un cardio à faible impact comme le vélo ou la marche sur terrain plat peut mieux convenir que les sauts.`},{title:`Progressez graduellement`,text:`Commencez par un mouvement et une quantité d’entraînement que vos genoux tolèrent. N’ajoutez de la charge, de la profondeur ou des répétitions que tant que les symptômes restent acceptables pendant et après l’entraînement. Ne continuez pas à tester une position douloureuse pour voir si elle « s’est arrangée toute seule ». Un conseil général d’exercice n’est ni un diagnostic ni un programme de rééducation.`},{title:`Quand demander de l’aide`,text:`Un genou très douloureux, visiblement déformé ou très gonflé, l’impossibilité de poser le pied, un blocage, de la fièvre avec rougeur ou des symptômes après une blessure importante nécessitent une évaluation professionnelle rapide. Les problèmes qui persistent doivent aussi être examinés.`},{title:`Avec TrainUp`,text:`Ajoutez vos genoux comme limitation dans Profil, avec une note, et indiquez si vous pouvez sauter. Le programme exclut alors les exercices qui ne conviennent pas. Si un exercice fait mal, « J’ai mal » y met fin et le garde hors de vos programmes jusqu’à ce que vous le réactiviez depuis Profil. Aucun exercice n’est garanti « sans danger pour les genoux » pour tout le monde.`}];var s=[{label:`NHS : douleur au genou et quand consulter`,url:`https://www.nhs.uk/symptoms/knee-pain/`},{label:`Prise de position 2026 de l’ACSM`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var u={sections:n,sources:s};export{u as default,n as sections,s as sources};